<template><div class="page"><div class="page-title"><h2>系统集成</h2><el-button type="primary" @click="sync()">全部同步</el-button></div><div class="grid-2"><div v-for="system in systems" :key="system.id" class="panel system-card"><div class="system-head"><div><h3>{{ system.name }}</h3><span class="muted">{{ system.code }} · {{ system.mode }}</span></div><el-tag :type="system.enabled ? 'success' : 'info'">{{ system.enabled ? '启用' : '预留' }}</el-tag></div><el-divider /><div class="system-row"><span>连接地址</span><span>{{ system.baseUrl || '未配置' }}</span></div><div class="system-row"><span>健康状态</span><span :class="system.lastHealthOk ? 'success' : 'danger'">{{ system.lastHealthOk ? '正常' : '未检查' }}</span></div><div class="system-actions"><el-button size="small" @click="health(system)" :disabled="!system.enabled">健康检查</el-button><el-button size="small" type="primary" @click="sync(system.code)" :disabled="!system.enabled">立即同步</el-button><el-button size="small" @click="edit(system)">配置</el-button></div></div></div><div class="panel"><h3>同步日志</h3><el-table :data="logs" stripe><el-table-column prop="systemCode" label="系统" /><el-table-column prop="status" label="状态" /><el-table-column prop="recordCount" label="记录数" /><el-table-column prop="errorMessage" label="错误" /><el-table-column prop="startedAt" label="开始时间" /></el-table></div><el-dialog v-model="dialog" title="系统配置"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="模式"><el-select v-model="form.mode"><el-option label="MOCK" value="MOCK" /><el-option label="HTTP" value="HTTP" /></el-select></el-form-item><el-form-item label="Base URL"><el-input v-model="form.baseUrl" /></el-form-item><el-form-item label="用户名"><el-input v-model="form.username" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" /></el-form-item><el-form-item label="API Key"><el-input v-model="form.apiKey" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import { reactive, ref } from 'vue'; import { integrationApi } from '../api'; import { ElMessage } from 'element-plus'
const systems=ref([]),logs=ref([]),dialog=ref(false),form=reactive({});async function load(){systems.value=await integrationApi.systems();logs.value=(await integrationApi.logs()).records||[]};async function health(row){await integrationApi.health(row.code);ElMessage.success('健康检查完成');load()};async function sync(code){await integrationApi.sync(code);ElMessage.success('同步完成');load()};function edit(row){Object.assign(form,row);dialog.value=true};async function save(){await integrationApi.update(form.id,form);dialog.value=false;load()};load()
</script>
<style scoped>.system-head,.system-row,.system-actions{display:flex;align-items:center;justify-content:space-between}.system-row{padding:7px 0;color:#65758b}.system-actions{justify-content:flex-end;margin-top:14px}</style>
